function validate([points, m]) {
  if (points.length < 2 || points.length > 50000) return 'points needs 2 to 50,000 values.';
  if (points.some(p => p < 1 || p > 1000000)) return 'Each value in points is between 1 and 1,000,000.';
  if (m < 1 || m > 1000000000) return 'm is between 1 and 1,000,000,000.';
  return null;
}

