function maxScore(points, m) {
  const n = points.length;

  function canReach(target) {
    let moves = 0;
    let carried = 0;
    for (let i = 0; i < n; i++) {
      const needed = Math.ceil(target / points[i]) - carried;
      if (i === n - 1 && needed <= 0) {
        break;
      }
      const arrivals = Math.max(needed, 1);
      moves += 2 * arrivals - 1;
      if (moves > m) {
        return false;
      }
      carried = arrivals - 1;
    }
    return true;
  }

  let low = 0;
  let high = Math.ceil(m / 2) * Math.min(...points);
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (canReach(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

