function maxScore(points, m) {
  // Try every walk of at most m moves from index -1 and keep the best smallest score seen along the way.
  const n = points.length;
  const score = new Array(n).fill(0);
  let best = 0;
  const walk = (index, movesLeft) => {
    best = Math.max(best, Math.min(...score));
    if (movesLeft === 0) return;
    for (const next of [index - 1, index + 1]) {
      if (next < 0 || next >= n) continue;
      score[next] += points[next];
      walk(next, movesLeft - 1);
      score[next] -= points[next];
    }
  };
  walk(-1, m);
  return best;
}

