function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    // Walks are enumerated by the brute force, so m stays small; values are tiny or occasionally huge.
    const top = rand() < 0.2 ? 1000000 : int(1, 10);
    const points = Array.from({ length: int(2, 5) }, () => int(1, top));
    return [points, int(1, 12)];
  }
  const n = int(1000, 2000);
  const shape = int(0, 2);
  // 0: huge values and the largest m; 1: small values and a moderate m; 2: equal values and m near n.
  const points = Array.from({ length: n }, () => shape === 0 ? int(1, 1000000) : shape === 1 ? int(1, 100) : 777);
  const m = shape === 0 ? int(900000000, 1000000000) : shape === 1 ? int(n, 20 * n) : int(n - 5, 3 * n);
  return [points, m];
}
